/** A minimal vi.fn(): calls through, records everything. */
function createSpy(impl = () => undefined) {
  // Write your solution here
  function spy(...args) {
    const value = impl(...args);
    spy.calls.push(args);
    spy.results.push({ type: 'return', value });
    return value;
  }
  spy.calls = [];
  spy.results = [];
  spy.callCount = 0;
  spy.calledWith = () => spy.calls.length > 0;
  return spy;
}

